-- ============================================================================
-- Function: public.rpc_get_city_faqs
-- Feature: Interactive pSEO
-- Purpose: Return published FAQs for visible content and FAQPage structured data.
-- Responsibilities: Preserve reviewed display order and answer type.
-- Notes: Hidden or draft FAQs never reach the public read model.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.rpc_get_city_faqs(p_input JSONB)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY INVOKER
SET search_path = ''
AS $$
DECLARE
  v_identity JSONB := private.parse_city_page_identity(p_input);
  v_context JSONB;
  v_city_slug TEXT;
  v_locale TEXT;
  v_city_page_id UUID;
  v_result JSONB;
BEGIN
  IF v_identity #>> '{error,code}' IS NOT NULL THEN
    RETURN private.build_rpc_error('[]'::JSONB, v_identity #>> '{error,code}', v_identity #>> '{error,message}');
  END IF;

  v_city_slug := v_identity #>> '{data,city_slug}';
  v_locale := v_identity #>> '{data,locale}';
  v_context := private.resolve_city_page_context(v_city_slug, v_locale);

  IF v_context #>> '{error,code}' IS NOT NULL THEN
    RETURN private.build_rpc_error('[]'::JSONB, v_context #>> '{error,code}', v_context #>> '{error,message}');
  END IF;

  v_city_page_id := (v_context #>> '{data,city_page_id}')::UUID;

  SELECT jsonb_build_object(
    'data', COALESCE(jsonb_agg(
      jsonb_build_object(
        'question', faq.question,
        'answer', faq.answer,
        'answer_type', faq.answer_type
      )
      ORDER BY faq.display_order
    ), '[]'::JSONB),
    'meta', '{}'::JSONB,
    'error', NULL
  )
  INTO v_result
  FROM public.city_page_faqs faq
  WHERE faq.city_page_id = v_city_page_id
    AND faq.status = 'published';

  RETURN v_result;
END;
$$;

REVOKE ALL ON FUNCTION public.rpc_get_city_faqs(JSONB)
FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_get_city_faqs(JSONB) TO service_role;

-- >>> supabase/sql_src/functions/pseo/rpc_get_city_page.sql

-- ============================================================================
-- Function: public.rpc_get_city_page
-- Feature: Interactive pSEO
-- Purpose: Return one bounded, frontend-ready city pSEO page payload.
-- Responsibilities: Validate identity, resolve reviewed content, and group page modules.
-- Notes: Indexability metadata is returned from Postgres and is never inferred by the transport.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.rpc_get_city_page(p_input JSONB)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY INVOKER
SET search_path = ''
AS $$
DECLARE
  ------------------------------------------------------------------
  -- Input
  ------------------------------------------------------------------
  v_city_slug TEXT;
  v_locale TEXT;
  v_route_direction TEXT;
  v_destination_limit INTEGER := 8;

  ------------------------------------------------------------------
  -- Resolved page
  ------------------------------------------------------------------
  v_city_id UUID;
  v_city_page_id UUID;
  v_pseo_page_id UUID;
  v_data_version UUID;
  v_identity JSONB;
  v_context JSONB;
  v_result JSONB;
BEGIN
  -- STEP 01: Parse the city-page identity shared by pSEO read RPCs.
  v_identity := private.parse_city_page_identity(p_input);

  IF v_identity #>> '{error,code}' IS NOT NULL THEN
    RETURN private.build_rpc_error(
      'null'::JSONB,
      v_identity #>> '{error,code}',
      v_identity #>> '{error,message}'
    );
  END IF;

  v_city_slug := v_identity #>> '{data,city_slug}';
  v_locale := v_identity #>> '{data,locale}';
  v_route_direction := v_identity #>> '{data,route_direction}';

  IF p_input ? 'destination_limit' THEN
    IF jsonb_typeof(p_input->'destination_limit') <> 'number' THEN
      RETURN private.build_rpc_error(
        'null'::JSONB,
        'ERR_INVALID_REQUEST',
        'destination_limit must be an integer.'
      );
    END IF;
    v_destination_limit := (p_input->>'destination_limit')::INTEGER;
  END IF;

  IF v_destination_limit NOT BETWEEN 1 AND 24 THEN
    RETURN private.build_rpc_error(
      'null'::JSONB,
      'ERR_INVALID_REQUEST',
      'destination_limit is outside accepted bounds.'
    );
  END IF;

  -- STEP 02: Resolve the city and reviewed page identity.
  v_context := private.resolve_city_page_context(
    v_city_slug,
    v_locale,
    v_route_direction
  );

  IF v_context #>> '{error,code}' IS NOT NULL THEN
    RETURN private.build_rpc_error(
      'null'::JSONB,
      v_context #>> '{error,code}',
      v_context #>> '{error,message}'
    );
  END IF;

  v_city_id := (v_context #>> '{data,city_id}')::UUID;
  v_city_page_id := (v_context #>> '{data,city_page_id}')::UUID;
  v_pseo_page_id := (v_context #>> '{data,pseo_page_id}')::UUID;
  v_data_version := (v_context #>> '{data,data_version}')::UUID;

  -- STEP 03: Assemble a bounded page payload from one published data version.
  SELECT jsonb_build_object(
    'data', jsonb_build_object(
      'city', jsonb_build_object(
        'id', city.id,
        'name', city.name,
        'slug', city.slug,
        'latitude', city.latitude,
        'longitude', city.longitude,
        'timezone', city.timezone
      ),
      'country', jsonb_build_object(
        'iso2', country.iso2,
        'iso3', country.iso3,
        'name', country.name,
        'slug', country.slug,
        'region', country.region,
        'subregion', country.subregion
      ),
      'page', jsonb_build_object(
        'h1', city_page.h1,
        'subheadline', city_page.subheadline,
        'seo_title', city_page.seo_title,
        'meta_description', city_page.meta_description,
        'og_title', city_page.og_title,
        'og_description', city_page.og_description,
        'og_image_path', city_page.og_image_path,
        'intro', city_page.intro,
        'airport_summary', city_page.airport_summary,
        'status', city_page.status
      ),
      'airports', COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'iata', airport.iata,
            'icao', airport.icao,
            'name', airport.name,
            'slug', airport.slug,
            'airport_type', airport.airport_type,
            'latitude', airport.latitude,
            'longitude', airport.longitude,
            'timezone', airport.timezone,
            'is_primary', airport.id = city_page.primary_airport_id,
            'direct_destinations', (
              SELECT count(DISTINCT city_route.destination_city_id)
              FROM public.pseo_direct_routes city_route
              WHERE city_route.origin_airport_id = airport.id
                AND city_route.data_version = v_data_version
            ),
            'airlines', (
              SELECT count(DISTINCT city_route.operating_airline_id)
              FROM public.pseo_direct_routes city_route
              WHERE city_route.origin_airport_id = airport.id
                AND city_route.data_version = v_data_version
            )
          )
          ORDER BY
            (airport.id = city_page.primary_airport_id) DESC,
            airport.iata
        )
        FROM public.airports airport
        WHERE airport.city_id = city.id
          AND airport.status = 'active'
      ), '[]'::JSONB),
      'quick_facts', jsonb_build_object(
        'airports', city_page.airport_count,
        'direct_destinations', city_page.direct_counterpart_city_count,
        'direct_countries', city_page.direct_counterpart_country_count,
        'airlines', city_page.airline_count,
        'shortest_route_minutes', city_page.shortest_route_minutes,
        'longest_route_minutes', city_page.longest_route_minutes
      ),
      'featured_destinations', COALESCE((
        SELECT jsonb_agg(destination_payload.payload ORDER BY destination_payload.position)
        FROM (
          SELECT
            row_number() OVER (
              ORDER BY
                destination.ranking_score DESC,
                destination_city.name
            ) AS position,
            jsonb_build_object(
              'city', jsonb_build_object(
                'name', destination_city.name,
                'slug', destination_city.slug
              ),
              'country', jsonb_build_object(
                'iso2', destination_country.iso2,
                'name', destination_country.name,
                'slug', destination_country.slug
              ),
              'origin_airports', COALESCE((
                SELECT jsonb_agg(DISTINCT origin_airport.iata ORDER BY origin_airport.iata)
                FROM public.pseo_direct_routes city_route
                JOIN public.airports origin_airport
                  ON origin_airport.id = city_route.origin_airport_id
                WHERE city_route.origin_city_id = destination.origin_city_id
                  AND city_route.destination_city_id = destination.destination_city_id
                  AND city_route.data_version = destination.data_version
              ), '[]'::JSONB),
              'destination_airports', COALESCE((
                SELECT jsonb_agg(DISTINCT destination_airport.iata ORDER BY destination_airport.iata)
                FROM public.pseo_direct_routes city_route
                JOIN public.airports destination_airport
                  ON destination_airport.id = city_route.destination_airport_id
                WHERE city_route.origin_city_id = destination.origin_city_id
                  AND city_route.destination_city_id = destination.destination_city_id
                  AND city_route.data_version = destination.data_version
              ), '[]'::JSONB),
              'airlines', COALESCE((
                SELECT jsonb_agg(DISTINCT airline.iata ORDER BY airline.iata)
                FROM public.pseo_direct_routes city_route
                JOIN public.airlines airline
                  ON airline.id = city_route.operating_airline_id
                WHERE city_route.origin_city_id = destination.origin_city_id
                  AND city_route.destination_city_id = destination.destination_city_id
                  AND city_route.data_version = destination.data_version
              ), '[]'::JSONB),
              'direct_route_count', destination.direct_route_count,
              'frequency_per_week', destination.frequency_per_week,
              'shortest_duration_minutes', destination.shortest_duration_minutes,
              'longest_duration_minutes', destination.longest_duration_minutes,
              'seasonality', destination.seasonality,
              'confidence_score', destination.confidence_score,
              'route_path', format(
                '/flights/%s-to-%s',
                city.slug,
                destination_city.slug
              )
            ) AS payload
          FROM public.city_destination_summaries destination
          JOIN public.cities destination_city
            ON destination_city.id = destination.destination_city_id
          JOIN public.countries destination_country
            ON destination_country.id = destination.destination_country_id
          WHERE destination.origin_city_id = city.id
            AND destination.data_version = v_data_version
          ORDER BY
            destination.ranking_score DESC,
            destination_city.name
          LIMIT v_destination_limit
        ) destination_payload
      ), '[]'::JSONB),
      'featured_airlines', COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'iata', airline_summary.iata,
            'name', airline_summary.name,
            'slug', airline_summary.slug,
            'direct_destinations', airline_summary.direct_destinations,
            'origin_airports', airline_summary.origin_airports
          )
          ORDER BY
            airline_summary.direct_destinations DESC,
            airline_summary.name
        )
        FROM (
          SELECT
            airline.iata,
            airline.name,
            airline.slug,
            count(DISTINCT city_route.destination_city_id) AS direct_destinations,
            jsonb_agg(DISTINCT origin_airport.iata ORDER BY origin_airport.iata) AS origin_airports
          FROM public.pseo_direct_routes city_route
          JOIN public.airlines airline
            ON airline.id = city_route.operating_airline_id
          JOIN public.airports origin_airport
            ON origin_airport.id = city_route.origin_airport_id
          WHERE city_route.origin_city_id = city.id
            AND city_route.data_version = v_data_version
          GROUP BY airline.id
        ) airline_summary
      ), '[]'::JSONB),
      'direct_countries', COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'iso2', country_summary.iso2,
            'name', country_summary.name,
            'slug', country_summary.slug,
            'direct_destinations', country_summary.direct_destinations
          )
          ORDER BY
            country_summary.direct_destinations DESC,
            country_summary.name
        )
        FROM (
          SELECT
            destination_country.iso2,
            destination_country.name,
            destination_country.slug,
            count(DISTINCT city_route.destination_city_id) AS direct_destinations
          FROM public.pseo_direct_routes city_route
          JOIN public.countries destination_country
            ON destination_country.id = city_route.destination_country_id
          WHERE city_route.origin_city_id = city.id
            AND city_route.data_version = v_data_version
          GROUP BY destination_country.id
        ) country_summary
      ), '[]'::JSONB),
      'faqs', COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'question', faq.question,
            'answer', faq.answer,
            'answer_type', faq.answer_type
          )
          ORDER BY faq.display_order
        )
        FROM public.city_page_faqs faq
        WHERE faq.city_page_id = city_page.id
          AND faq.status = 'published'
      ), '[]'::JSONB),
      'internal_link_groups', COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'cluster', link_group.link_cluster,
            'links', link_group.links
          )
          ORDER BY link_group.cluster_order
        )
        FROM (
          SELECT
            internal_link.link_cluster,
            min(internal_link.display_order) AS cluster_order,
            jsonb_agg(
              jsonb_build_object(
                'title', target_page.display_title,
                'path', target_page.canonical_path,
                'anchor_text', internal_link.anchor_text,
                'secondary_text', internal_link.secondary_text,
                'is_featured', internal_link.is_featured
              )
              ORDER BY
                internal_link.display_order,
                internal_link.relevance_score DESC,
                target_page.canonical_path
            ) AS links
          FROM public.pseo_internal_links internal_link
          JOIN public.pseo_pages target_page
            ON target_page.id = internal_link.target_page_id
          WHERE internal_link.source_page_id = v_pseo_page_id
            AND target_page.status <> 'archived'
          GROUP BY internal_link.link_cluster
        ) link_group
      ), '[]'::JSONB)
    ),
    'meta', jsonb_build_object(
      'canonical_path', pseo_page.canonical_path,
      'is_indexable', city_page.is_indexable,
      'noindex_reason', city_page.noindex_reason,
      'data_version', city_page.data_version,
      'generated_at', city_page.generated_at,
      'source_freshness_at', city_page.source_freshness_at
    ),
    'error', NULL
  )
  INTO v_result
  FROM public.cities city
  JOIN public.countries country
    ON country.id = city.country_id
  JOIN public.city_pages city_page
    ON city_page.id = v_city_page_id
  JOIN public.pseo_pages pseo_page
    ON pseo_page.id = city_page.pseo_page_id
  WHERE city.id = v_city_id;

  RETURN v_result;
END;
$$;

REVOKE ALL ON FUNCTION public.rpc_get_city_page(JSONB)
FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_get_city_page(JSONB) TO service_role;

-- >>> supabase/sql_src/functions/pseo/rpc_search_city_direct_routes.sql

-- ============================================================================
-- Function: public.rpc_search_city_direct_routes
-- Feature: Interactive pSEO
-- Purpose: Filter, facet, rank, and paginate direct destinations from a city.
-- Responsibilities: Validate bounded filters and derive results/facets from one filtered set.
-- Notes: Filter query parameters do not create indexable page identities.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.rpc_search_city_direct_routes(p_input JSONB)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY INVOKER
SET search_path = ''
AS $$
DECLARE
  ------------------------------------------------------------------
  -- Route identity and version
  ------------------------------------------------------------------
  v_city_slug TEXT;
  v_locale TEXT;
  v_city_id UUID;
  v_data_version UUID;

  ------------------------------------------------------------------
  -- Filters and pagination
  ------------------------------------------------------------------
  v_origin_airports TEXT[] := '{}'::TEXT[];
  v_airlines TEXT[] := '{}'::TEXT[];
  v_destination_countries TEXT[] := '{}'::TEXT[];
  v_max_duration_minutes INTEGER;
  v_departure_window TEXT;
  v_limit INTEGER := 20;
  v_offset INTEGER := 0;

  ------------------------------------------------------------------
  -- Result
  ------------------------------------------------------------------
  v_identity JSONB;
  v_context JSONB;
  v_result JSONB;
BEGIN
  -- STEP 01: Parse the city-page identity shared by pSEO read RPCs.
  v_identity := private.parse_city_page_identity(p_input);

  IF v_identity #>> '{error,code}' IS NOT NULL THEN
    RETURN private.build_rpc_error(
      '[]'::JSONB,
      v_identity #>> '{error,code}',
      v_identity #>> '{error,message}'
    );
  END IF;

  v_city_slug := v_identity #>> '{data,city_slug}';
  v_locale := v_identity #>> '{data,locale}';

  IF p_input ? 'origin_airports' THEN
    IF jsonb_typeof(p_input->'origin_airports') <> 'array' THEN
      RETURN jsonb_build_object(
        'data', '[]'::JSONB,
        'meta', '{}'::JSONB,
        'error', jsonb_build_object(
          'code', 'ERR_INVALID_REQUEST',
          'message', 'origin_airports must be an array.'
        )
      );
    END IF;
    IF EXISTS (
      SELECT 1
      FROM jsonb_array_elements_text(p_input->'origin_airports') code
      WHERE private.normalize_airport_iata(code) IS NULL
    ) THEN
      RETURN jsonb_build_object(
        'data', '[]'::JSONB,
        'meta', '{}'::JSONB,
        'error', jsonb_build_object(
          'code', 'ERR_INVALID_REQUEST',
          'message', 'origin_airports contains an invalid IATA code.'
        )
      );
    END IF;
    SELECT COALESCE(
      array_agg(DISTINCT private.normalize_airport_iata(code)),
      '{}'::TEXT[]
    )
    INTO v_origin_airports
    FROM jsonb_array_elements_text(p_input->'origin_airports') code;
  END IF;

  IF p_input ? 'airlines' THEN
    IF jsonb_typeof(p_input->'airlines') <> 'array' THEN
      RETURN jsonb_build_object(
        'data', '[]'::JSONB,
        'meta', '{}'::JSONB,
        'error', jsonb_build_object(
          'code', 'ERR_INVALID_REQUEST',
          'message', 'airlines must be an array.'
        )
      );
    END IF;
    IF EXISTS (
      SELECT 1
      FROM jsonb_array_elements_text(p_input->'airlines') code
      WHERE private.normalize_airline_iata(code) IS NULL
    ) THEN
      RETURN jsonb_build_object(
        'data', '[]'::JSONB,
        'meta', '{}'::JSONB,
        'error', jsonb_build_object(
          'code', 'ERR_INVALID_REQUEST',
          'message', 'airlines contains an invalid IATA code.'
        )
      );
    END IF;
    SELECT COALESCE(
      array_agg(DISTINCT private.normalize_airline_iata(code)),
      '{}'::TEXT[]
    )
    INTO v_airlines
    FROM jsonb_array_elements_text(p_input->'airlines') code;
  END IF;

  IF p_input ? 'destination_countries' THEN
    IF jsonb_typeof(p_input->'destination_countries') <> 'array' THEN
      RETURN jsonb_build_object(
        'data', '[]'::JSONB,
        'meta', '{}'::JSONB,
        'error', jsonb_build_object(
          'code', 'ERR_INVALID_REQUEST',
          'message', 'destination_countries must be an array.'
        )
      );
    END IF;
    SELECT COALESCE(array_agg(DISTINCT upper(btrim(code))), '{}'::TEXT[])
    INTO v_destination_countries
    FROM jsonb_array_elements_text(p_input->'destination_countries') code;
    IF EXISTS (
      SELECT 1
      FROM UNNEST(v_destination_countries) code
      WHERE code !~ '^[A-Z]{2}$'
    ) THEN
      RETURN jsonb_build_object(
        'data', '[]'::JSONB,
        'meta', '{}'::JSONB,
        'error', jsonb_build_object(
          'code', 'ERR_INVALID_REQUEST',
          'message', 'destination_countries contains an invalid ISO code.'
        )
      );
    END IF;
  END IF;

  IF p_input ? 'max_duration_minutes' THEN
    IF jsonb_typeof(p_input->'max_duration_minutes') <> 'number' THEN
      RETURN jsonb_build_object(
        'data', '[]'::JSONB,
        'meta', '{}'::JSONB,
        'error', jsonb_build_object(
          'code', 'ERR_INVALID_REQUEST',
          'message', 'max_duration_minutes must be an integer.'
        )
      );
    END IF;
    v_max_duration_minutes := (p_input->>'max_duration_minutes')::INTEGER;
    IF v_max_duration_minutes NOT BETWEEN 1 AND 1440 THEN
      RETURN jsonb_build_object(
        'data', '[]'::JSONB,
        'meta', '{}'::JSONB,
        'error', jsonb_build_object(
          'code', 'ERR_INVALID_REQUEST',
          'message', 'max_duration_minutes is outside accepted bounds.'
        )
      );
    END IF;
  END IF;

  v_departure_window := nullif(lower(btrim(COALESCE(p_input->>'departure_window', ''))), '');
  IF v_departure_window IS NOT NULL
    AND v_departure_window NOT IN ('morning', 'afternoon', 'evening', 'night')
  THEN
    RETURN jsonb_build_object(
      'data', '[]'::JSONB,
      'meta', '{}'::JSONB,
      'error', jsonb_build_object(
        'code', 'ERR_INVALID_REQUEST',
        'message', 'departure_window is not supported.'
      )
    );
  END IF;

  IF p_input ? 'limit' THEN
    IF jsonb_typeof(p_input->'limit') <> 'number' THEN
      RETURN jsonb_build_object(
        'data', '[]'::JSONB,
        'meta', '{}'::JSONB,
        'error', jsonb_build_object(
          'code', 'ERR_INVALID_REQUEST',
          'message', 'limit must be an integer.'
        )
      );
    END IF;
    v_limit := (p_input->>'limit')::INTEGER;
  END IF;

  IF p_input ? 'offset' THEN
    IF jsonb_typeof(p_input->'offset') <> 'number' THEN
      RETURN jsonb_build_object(
        'data', '[]'::JSONB,
        'meta', '{}'::JSONB,
        'error', jsonb_build_object(
          'code', 'ERR_INVALID_REQUEST',
          'message', 'offset must be an integer.'
        )
      );
    END IF;
    v_offset := (p_input->>'offset')::INTEGER;
  END IF;

  IF v_limit NOT BETWEEN 1 AND 100 OR v_offset NOT BETWEEN 0 AND 10000 THEN
    RETURN jsonb_build_object(
      'data', '[]'::JSONB,
      'meta', '{}'::JSONB,
      'error', jsonb_build_object(
        'code', 'ERR_INVALID_REQUEST',
        'message', 'Pagination is outside accepted bounds.'
      )
    );
  END IF;

  -- STEP 02: Resolve the city and current page version.
  v_context := private.resolve_city_page_context(
    v_city_slug,
    v_locale
  );

  IF v_context #>> '{error,code}' IS NOT NULL THEN
    RETURN private.build_rpc_error(
      '[]'::JSONB,
      v_context #>> '{error,code}',
      v_context #>> '{error,message}'
    );
  END IF;

  v_city_id := (v_context #>> '{data,city_id}')::UUID;
  v_data_version := (v_context #>> '{data,data_version}')::UUID;

  -- STEP 03: Filter once and derive results and facets from the same relation.
  WITH filtered AS MATERIALIZED (
    SELECT
      city_route.*,
      origin_airport.iata AS origin_airport_iata,
      destination_airport.iata AS destination_airport_iata,
      operating_airline.iata AS operating_airline_iata,
      operating_airline.name AS operating_airline_name,
      destination_country.iso2 AS destination_country_iso2,
      destination_country.name AS destination_country_name,
      destination_city.name AS destination_city_name,
      destination_city.slug AS destination_city_slug
    FROM public.pseo_direct_routes city_route
    JOIN public.airports origin_airport
      ON origin_airport.id = city_route.origin_airport_id
    JOIN public.airports destination_airport
      ON destination_airport.id = city_route.destination_airport_id
    JOIN public.airlines operating_airline
      ON operating_airline.id = city_route.operating_airline_id
    JOIN public.countries destination_country
      ON destination_country.id = city_route.destination_country_id
    JOIN public.cities destination_city
      ON destination_city.id = city_route.destination_city_id
    WHERE city_route.origin_city_id = v_city_id
      AND city_route.data_version = v_data_version
      AND (
        cardinality(v_origin_airports) = 0
        OR origin_airport.iata = ANY(v_origin_airports)
      )
      AND (
        cardinality(v_airlines) = 0
        OR operating_airline.iata = ANY(v_airlines)
      )
      AND (
        cardinality(v_destination_countries) = 0
        OR destination_country.iso2 = ANY(v_destination_countries)
      )
      AND (
        v_max_duration_minutes IS NULL
        OR city_route.shortest_duration_minutes <= v_max_duration_minutes
      )
      AND (
        v_departure_window IS NULL
        OR (
          v_departure_window = 'morning'
          AND city_route.earliest_departure_time >= TIME '05:00'
          AND city_route.earliest_departure_time < TIME '12:00'
        )
        OR (
          v_departure_window = 'afternoon'
          AND city_route.earliest_departure_time >= TIME '12:00'
          AND city_route.earliest_departure_time < TIME '17:00'
        )
        OR (
          v_departure_window = 'evening'
          AND city_route.earliest_departure_time >= TIME '17:00'
          AND city_route.earliest_departure_time < TIME '21:00'
        )
        OR (
          v_departure_window = 'night'
          AND (
            city_route.earliest_departure_time >= TIME '21:00'
            OR city_route.earliest_departure_time < TIME '05:00'
          )
        )
      )
  ),
  destinations AS (
    SELECT
      filtered.destination_city_id,
      filtered.destination_city_name,
      filtered.destination_city_slug,
      filtered.destination_country_iso2,
      filtered.destination_country_name,
      jsonb_agg(
        DISTINCT filtered.origin_airport_iata
        ORDER BY filtered.origin_airport_iata
      ) AS origin_airports,
      jsonb_agg(
        DISTINCT filtered.destination_airport_iata
        ORDER BY filtered.destination_airport_iata
      ) AS destination_airports,
      jsonb_agg(
        DISTINCT filtered.operating_airline_iata
        ORDER BY filtered.operating_airline_iata
      ) AS airlines,
      count(*) AS direct_route_count,
      CASE
        WHEN count(filtered.frequency_per_week) = 0 THEN NULL
        ELSE sum(filtered.frequency_per_week)
      END AS frequency_per_week,
      min(filtered.shortest_duration_minutes) AS shortest_duration_minutes,
      max(filtered.longest_duration_minutes) AS longest_duration_minutes,
      min(filtered.confidence_score) AS confidence_score
    FROM filtered
    GROUP BY
      filtered.destination_city_id,
      filtered.destination_city_name,
      filtered.destination_city_slug,
      filtered.destination_country_iso2,
      filtered.destination_country_name
  ),
  page AS (
    SELECT destinations.*
    FROM destinations
    ORDER BY
      COALESCE(destinations.frequency_per_week, 0) DESC,
      destinations.shortest_duration_minutes,
      destinations.confidence_score DESC,
      destinations.destination_city_name
    LIMIT v_limit
    OFFSET v_offset
  )
  SELECT jsonb_build_object(
    'data', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'city', jsonb_build_object(
            'name', page.destination_city_name,
            'slug', page.destination_city_slug
          ),
          'country', jsonb_build_object(
            'iso2', page.destination_country_iso2,
            'name', page.destination_country_name
          ),
          'origin_airports', page.origin_airports,
          'destination_airports', page.destination_airports,
          'airlines', page.airlines,
          'direct_route_count', page.direct_route_count,
          'frequency_per_week', page.frequency_per_week,
          'shortest_duration_minutes', page.shortest_duration_minutes,
          'longest_duration_minutes', page.longest_duration_minutes,
          'confidence_score', page.confidence_score,
          'route_path', format(
            '/flights/%s-to-%s',
            v_city_slug,
            page.destination_city_slug
          )
        )
        ORDER BY
          COALESCE(page.frequency_per_week, 0) DESC,
          page.shortest_duration_minutes,
          page.confidence_score DESC,
          page.destination_city_name
      )
      FROM page
    ), '[]'::JSONB),
    'meta', jsonb_build_object(
      'total', (SELECT count(*) FROM destinations),
      'limit', v_limit,
      'offset', v_offset,
      'data_version', v_data_version,
      'facets', jsonb_build_object(
        'airports', COALESCE((
          SELECT jsonb_agg(
            jsonb_build_object(
              'value', airport_facet.origin_airport_iata,
              'count', airport_facet.destination_count
            )
            ORDER BY airport_facet.origin_airport_iata
          )
          FROM (
            SELECT
              filtered.origin_airport_iata,
              count(DISTINCT filtered.destination_city_id) AS destination_count
            FROM filtered
            GROUP BY filtered.origin_airport_iata
          ) airport_facet
        ), '[]'::JSONB),
        'airlines', COALESCE((
          SELECT jsonb_agg(
            jsonb_build_object(
              'value', airline_facet.operating_airline_iata,
              'label', airline_facet.operating_airline_name,
              'count', airline_facet.destination_count
            )
            ORDER BY airline_facet.operating_airline_iata
          )
          FROM (
            SELECT
              filtered.operating_airline_iata,
              filtered.operating_airline_name,
              count(DISTINCT filtered.destination_city_id) AS destination_count
            FROM filtered
            GROUP BY
              filtered.operating_airline_iata,
              filtered.operating_airline_name
          ) airline_facet
        ), '[]'::JSONB),
        'countries', COALESCE((
          SELECT jsonb_agg(
            jsonb_build_object(
              'value', country_facet.destination_country_iso2,
              'label', country_facet.destination_country_name,
              'count', country_facet.destination_count
            )
            ORDER BY country_facet.destination_country_name
          )
          FROM (
            SELECT
              filtered.destination_country_iso2,
              filtered.destination_country_name,
              count(DISTINCT filtered.destination_city_id) AS destination_count
            FROM filtered
            GROUP BY
              filtered.destination_country_iso2,
              filtered.destination_country_name
          ) country_facet
        ), '[]'::JSONB)
      )
    ),
    'error', NULL
  )
  INTO v_result;

  RETURN v_result;
END;
$$;

REVOKE ALL ON FUNCTION public.rpc_search_city_direct_routes(JSONB)
FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_search_city_direct_routes(JSONB) TO service_role;

-- >>> supabase/sql_src/functions/pseo/rpc_get_airport_page.sql

-- ============================================================================
-- Function: public.rpc_get_airport_page
-- Feature: Interactive pSEO
-- Purpose: Return one frontend-ready airport landing-page payload.
-- Responsibilities: Compose identity, route summaries, reviewed guidance, and page metadata.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.rpc_get_airport_page(p_input JSONB)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY INVOKER
SET search_path = ''
AS $$
DECLARE
  v_identity JSONB;
  v_context JSONB;
  v_airport_iata TEXT;
  v_locale TEXT;
  v_airport_id UUID;
  v_airport_page_id UUID;
  v_pseo_page_id UUID;
  v_data_version UUID;
  v_route_limit INTEGER := 8;
  v_result JSONB;
BEGIN
  v_identity := private.parse_airport_page_identity(p_input);

  IF v_identity->'error' IS NOT NULL
    AND v_identity->'error' <> 'null'::JSONB
  THEN
    RETURN jsonb_build_object('data', NULL, 'meta', NULL, 'error', v_identity->'error');
  END IF;

  v_airport_iata := v_identity #>> '{data,airport_iata}';
  v_locale := v_identity #>> '{data,locale}';

  IF p_input ? 'route_limit' THEN
    IF jsonb_typeof(p_input->'route_limit') <> 'number'
      OR (p_input->>'route_limit')::NUMERIC <> trunc((p_input->>'route_limit')::NUMERIC)
      OR (p_input->>'route_limit')::INTEGER NOT BETWEEN 1 AND 24
    THEN
      RETURN jsonb_build_object(
        'data', NULL,
        'meta', NULL,
        'error', jsonb_build_object(
          'code', 'ERR_INVALID_REQUEST',
          'message', 'route_limit must be an integer between 1 and 24.'
        )
      );
    END IF;

    v_route_limit := (p_input->>'route_limit')::INTEGER;
  END IF;

  v_context := private.resolve_airport_page_context(v_airport_iata, v_locale);

  IF v_context->'error' IS NOT NULL
    AND v_context->'error' <> 'null'::JSONB
  THEN
    RETURN jsonb_build_object('data', NULL, 'meta', NULL, 'error', v_context->'error');
  END IF;

  v_airport_id := (v_context #>> '{data,airport_id}')::UUID;
  v_airport_page_id := (v_context #>> '{data,airport_page_id}')::UUID;
  v_pseo_page_id := (v_context #>> '{data,pseo_page_id}')::UUID;
  v_data_version := (v_context #>> '{data,data_version}')::UUID;

  SELECT jsonb_build_object(
    'data', jsonb_build_object(
      'airport', jsonb_build_object(
        'id', airport.id,
        'iata', airport.iata,
        'icao', airport.icao,
        'name', airport.name,
        'slug', airport.slug,
        'image_path', airport.image_path,
        'type', airport.airport_type,
        'timezone', airport.timezone,
        'latitude', airport.latitude,
        'longitude', airport.longitude,
        'city', jsonb_build_object(
          'id', city.id,
          'name', city.name,
          'slug', city.slug
        ),
        'country', jsonb_build_object(
          'id', country.id,
          'code', country.iso2,
          'name', country.name,
          'slug', country.slug
        )
      ),
      'seo', jsonb_build_object(
        'h1', airport_page.h1,
        'subheadline', airport_page.subheadline,
        'title', airport_page.seo_title,
        'meta_description', airport_page.meta_description,
        'og_title', airport_page.og_title,
        'og_description', airport_page.og_description,
        'og_image_path', airport_page.og_image_path
      ),
      'content', jsonb_build_object(
        'intro', airport_page.intro,
        'route_summary', airport_page.route_summary,
        'access_summary', airport_page.access_summary,
        'parking_summary', airport_page.parking_summary,
        'lounge_summary', airport_page.lounge_summary
      ),
      'quick_facts', jsonb_build_object(
        'outbound_destinations', airport_page.outbound_destination_count,
        'outbound_countries', airport_page.outbound_country_count,
        'inbound_origins', airport_page.inbound_origin_count,
        'inbound_countries', airport_page.inbound_country_count,
        'airlines', airport_page.airline_count,
        'shortest_route_minutes', airport_page.shortest_route_minutes,
        'longest_route_minutes', airport_page.longest_route_minutes
      ),
      'featured_outbound_routes', COALESCE((
        SELECT jsonb_agg(to_jsonb(route_item) ORDER BY route_item.rank_order)
        FROM (
          SELECT
            destination_airport.iata AS airport_iata,
            destination_airport.name AS airport_name,
            destination_city.name AS city_name,
            destination_city.slug AS city_slug,
            destination_country.iso2 AS country_code,
            destination_country.name AS country_name,
            min(route.shortest_duration_minutes) AS shortest_duration_minutes,
            count(DISTINCT route.operating_airline_id)::INTEGER AS airline_count,
            row_number() OVER (
              ORDER BY
                COALESCE(sum(route.frequency_per_week), 0) DESC,
                count(*) DESC,
                destination_city.name,
                destination_airport.iata
            ) AS rank_order
          FROM public.pseo_direct_routes route
          JOIN public.airports destination_airport
            ON destination_airport.id = route.destination_airport_id
          JOIN public.cities destination_city
            ON destination_city.id = route.destination_city_id
          JOIN public.countries destination_country
            ON destination_country.id = route.destination_country_id
          WHERE route.origin_airport_id = v_airport_id
            AND route.data_version = v_data_version
          GROUP BY
            destination_airport.iata,
            destination_airport.name,
            destination_city.name,
            destination_city.slug,
            destination_country.iso2,
            destination_country.name
          ORDER BY rank_order
          LIMIT v_route_limit
        ) route_item
      ), '[]'::JSONB),
      'featured_inbound_routes', COALESCE((
        SELECT jsonb_agg(to_jsonb(route_item) ORDER BY route_item.rank_order)
        FROM (
          SELECT
            origin_airport.iata AS airport_iata,
            origin_airport.name AS airport_name,
            origin_city.name AS city_name,
            origin_city.slug AS city_slug,
            origin_country.iso2 AS country_code,
            origin_country.name AS country_name,
            min(route.shortest_duration_minutes) AS shortest_duration_minutes,
            count(DISTINCT route.operating_airline_id)::INTEGER AS airline_count,
            row_number() OVER (
              ORDER BY
                COALESCE(sum(route.frequency_per_week), 0) DESC,
                count(*) DESC,
                origin_city.name,
                origin_airport.iata
            ) AS rank_order
          FROM public.pseo_direct_routes route
          JOIN public.airports origin_airport
            ON origin_airport.id = route.origin_airport_id
          JOIN public.cities origin_city
            ON origin_city.id = route.origin_city_id
          JOIN public.countries origin_country
            ON origin_country.id = route.origin_country_id
          WHERE route.destination_airport_id = v_airport_id
            AND route.data_version = v_data_version
          GROUP BY
            origin_airport.iata,
            origin_airport.name,
            origin_city.name,
            origin_city.slug,
            origin_country.iso2,
            origin_country.name
          ORDER BY rank_order
          LIMIT v_route_limit
        ) route_item
      ), '[]'::JSONB),
      'airlines', COALESCE((
        SELECT jsonb_agg(to_jsonb(airline_item) ORDER BY airline_item.route_count DESC, airline_item.name)
        FROM (
          SELECT
            airline.iata,
            airline.name,
            airline.slug,
            airline.logo_path,
            count(DISTINCT route.flight_route_id)::INTEGER AS route_count
          FROM public.pseo_direct_routes route
          JOIN public.airlines airline
            ON airline.id = route.operating_airline_id
          WHERE route.data_version = v_data_version
            AND (
              route.origin_airport_id = v_airport_id
              OR route.destination_airport_id = v_airport_id
            )
          GROUP BY airline.iata, airline.name, airline.slug, airline.logo_path
        ) airline_item
      ), '[]'::JSONB),
      'access_options', COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'type', access.access_type,
            'name', access.name,
            'destination_label', access.destination_label,
            'summary', access.summary,
            'duration_min_minutes', access.duration_min_minutes,
            'duration_max_minutes', access.duration_max_minutes,
            'price_min', access.price_min,
            'price_max', access.price_max,
            'currency_code', access.currency_code,
            'operating_hours_summary', access.operating_hours_summary,
            'booking_url', access.booking_url,
            'source_url', access.primary_source_url,
            'last_verified_at', access.last_verified_at
          )
          ORDER BY access.display_order
        )
        FROM public.airport_access_options access
        WHERE access.airport_page_id = v_airport_page_id
          AND access.status = 'published'
      ), '[]'::JSONB),
      'parking', (
        SELECT jsonb_build_object(
          'summary', parking.summary,
          'short_stay_available', parking.short_stay_available,
          'long_stay_available', parking.long_stay_available,
          'reservation_available', parking.reservation_available,
          'shuttle_available', parking.shuttle_available,
          'official_url', parking.official_url,
          'source_url', parking.primary_source_url,
          'last_verified_at', parking.last_verified_at
        )
        FROM public.airport_parking_information parking
        WHERE parking.airport_page_id = v_airport_page_id
          AND parking.status = 'published'
      ),
      'lounges', COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'name', lounge.name,
            'location_summary', lounge.location_summary,
            'location_type', lounge.location_type,
            'access_summary', lounge.access_summary,
            'amenities', to_jsonb(lounge.amenities),
            'official_url', lounge.official_url,
            'source_url', lounge.primary_source_url,
            'last_verified_at', lounge.last_verified_at
          )
          ORDER BY lounge.display_order
        )
        FROM public.airport_lounges lounge
        WHERE lounge.airport_page_id = v_airport_page_id
          AND lounge.status = 'published'
      ), '[]'::JSONB),
      'notices', COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'type', notice.notice_type,
            'title', notice.title,
            'body', notice.body,
            'severity', notice.severity,
            'source_url', notice.primary_source_url,
            'last_verified_at', notice.last_verified_at
          )
          ORDER BY notice.display_order
        )
        FROM public.airport_page_notices notice
        WHERE notice.airport_page_id = v_airport_page_id
          AND notice.status = 'published'
      ), '[]'::JSONB),
      'faqs', COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'question', faq.question,
            'answer', faq.answer,
            'answer_type', faq.answer_type
          )
          ORDER BY faq.display_order
        )
        FROM public.airport_page_faqs faq
        WHERE faq.airport_page_id = v_airport_page_id
          AND faq.status = 'published'
      ), '[]'::JSONB),
      'internal_link_groups', COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'cluster', links.link_cluster,
            'links', links.items
          )
          ORDER BY links.link_cluster
        )
        FROM (
          SELECT
            link.link_cluster,
            jsonb_agg(
              jsonb_build_object(
                'anchor_text', link.anchor_text,
                'secondary_text', link.secondary_text,
                'path', target.canonical_path
              )
              ORDER BY link.display_order
            ) AS items
          FROM public.pseo_internal_links link
          JOIN public.pseo_pages target
            ON target.id = link.target_page_id
          WHERE link.source_page_id = v_pseo_page_id
            AND target.status = 'published'
          GROUP BY link.link_cluster
        ) links
      ), '[]'::JSONB)
    ),
    'meta', jsonb_build_object(
      'canonical_path', pseo_page.canonical_path,
      'is_indexable', airport_page.is_indexable,
      'noindex_reason', airport_page.noindex_reason,
      'data_version', airport_page.data_version,
      'source_freshness_at', airport_page.source_freshness_at,
      'generated_at', airport_page.generated_at
    ),
    'error', NULL
  )
  INTO v_result
  FROM public.airport_pages airport_page
  JOIN public.pseo_pages pseo_page
    ON pseo_page.id = airport_page.pseo_page_id
  JOIN public.airports airport
    ON airport.id = airport_page.airport_id
  LEFT JOIN public.cities city
    ON city.id = airport.city_id
  JOIN public.countries country
    ON country.id = airport.country_id
  WHERE airport_page.id = v_airport_page_id;

  RETURN v_result;
END;
$$;

REVOKE ALL ON FUNCTION public.rpc_get_airport_page(JSONB)
FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_get_airport_page(JSONB) TO service_role;

-- >>> supabase/sql_src/functions/pseo/rpc_search_airport_direct_routes.sql

-- ============================================================================
-- Function: public.rpc_search_airport_direct_routes
-- Feature: Interactive pSEO
-- Purpose: Search inbound or outbound direct routes for one airport.
-- Responsibilities: Validate bounded filters and derive results/facets from one filtered relation.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.rpc_search_airport_direct_routes(p_input JSONB)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY INVOKER
SET search_path = ''
AS $$
DECLARE
  v_identity JSONB;
  v_context JSONB;
  v_airport_iata TEXT;
  v_locale TEXT;
  v_direction TEXT;
  v_airport_id UUID;
  v_airport_page_id UUID;
  v_data_version UUID;
  v_airlines TEXT[] := '{}'::TEXT[];
  v_countries TEXT[] := '{}'::TEXT[];
  v_seasonality TEXT;
  v_max_duration_minutes INTEGER;
  v_limit INTEGER := 20;
  v_offset INTEGER := 0;
  v_result JSONB;
BEGIN
  v_identity := private.parse_airport_page_identity(p_input);

  IF v_identity->'error' IS NOT NULL
    AND v_identity->'error' <> 'null'::JSONB
  THEN
    RETURN jsonb_build_object('data', NULL, 'meta', NULL, 'error', v_identity->'error');
  END IF;

  v_airport_iata := v_identity #>> '{data,airport_iata}';
  v_locale := v_identity #>> '{data,locale}';
  v_direction := lower(btrim(COALESCE(p_input->>'direction', 'outbound')));

  IF v_direction NOT IN ('outbound', 'inbound') THEN
    RETURN jsonb_build_object(
      'data', NULL,
      'meta', NULL,
      'error', jsonb_build_object(
        'code', 'ERR_INVALID_REQUEST',
        'message', 'direction must be outbound or inbound.'
      )
    );
  END IF;

  IF p_input ? 'airlines' THEN
    IF jsonb_typeof(p_input->'airlines') <> 'array'
      OR EXISTS (
        SELECT 1
        FROM jsonb_array_elements_text(p_input->'airlines') item
        WHERE upper(btrim(item)) !~ '^[A-Z0-9]{2}$'
      )
    THEN
      RETURN jsonb_build_object(
        'data', NULL,
        'meta', NULL,
        'error', jsonb_build_object(
          'code', 'ERR_INVALID_REQUEST',
          'message', 'airlines must contain valid IATA codes.'
        )
      );
    END IF;

    SELECT COALESCE(array_agg(DISTINCT upper(btrim(item))), '{}'::TEXT[])
    INTO v_airlines
    FROM jsonb_array_elements_text(p_input->'airlines') item;
  END IF;

  IF p_input ? 'countries' THEN
    IF jsonb_typeof(p_input->'countries') <> 'array'
      OR EXISTS (
        SELECT 1
        FROM jsonb_array_elements_text(p_input->'countries') item
        WHERE upper(btrim(item)) !~ '^[A-Z]{2}$'
      )
    THEN
      RETURN jsonb_build_object(
        'data', NULL,
        'meta', NULL,
        'error', jsonb_build_object(
          'code', 'ERR_INVALID_REQUEST',
          'message', 'countries must contain valid ISO-2 codes.'
        )
      );
    END IF;

    SELECT COALESCE(array_agg(DISTINCT upper(btrim(item))), '{}'::TEXT[])
    INTO v_countries
    FROM jsonb_array_elements_text(p_input->'countries') item;
  END IF;

  IF p_input ? 'seasonality' THEN
    v_seasonality := lower(btrim(p_input->>'seasonality'));
    IF v_seasonality NOT IN ('year_round', 'seasonal', 'unknown') THEN
      RETURN jsonb_build_object(
        'data', NULL,
        'meta', NULL,
        'error', jsonb_build_object(
          'code', 'ERR_INVALID_REQUEST',
          'message', 'seasonality is invalid.'
        )
      );
    END IF;
  END IF;

  IF p_input ? 'max_duration_minutes' THEN
    IF jsonb_typeof(p_input->'max_duration_minutes') <> 'number'
      OR (p_input->>'max_duration_minutes')::NUMERIC
        <> trunc((p_input->>'max_duration_minutes')::NUMERIC)
      OR (p_input->>'max_duration_minutes')::INTEGER <= 0
    THEN
      RETURN jsonb_build_object(
        'data', NULL,
        'meta', NULL,
        'error', jsonb_build_object(
          'code', 'ERR_INVALID_REQUEST',
          'message', 'max_duration_minutes must be a positive integer.'
        )
      );
    END IF;
    v_max_duration_minutes := (p_input->>'max_duration_minutes')::INTEGER;
  END IF;

  IF p_input ? 'limit' THEN
    IF jsonb_typeof(p_input->'limit') <> 'number'
      OR (p_input->>'limit')::NUMERIC <> trunc((p_input->>'limit')::NUMERIC)
      OR (p_input->>'limit')::INTEGER NOT BETWEEN 1 AND 100
    THEN
      RETURN jsonb_build_object(
        'data', NULL,
        'meta', NULL,
        'error', jsonb_build_object(
          'code', 'ERR_INVALID_REQUEST',
          'message', 'limit must be an integer between 1 and 100.'
        )
      );
    END IF;
    v_limit := (p_input->>'limit')::INTEGER;
  END IF;

  IF p_input ? 'offset' THEN
    IF jsonb_typeof(p_input->'offset') <> 'number'
      OR (p_input->>'offset')::NUMERIC <> trunc((p_input->>'offset')::NUMERIC)
      OR (p_input->>'offset')::INTEGER < 0
    THEN
      RETURN jsonb_build_object(
        'data', NULL,
        'meta', NULL,
        'error', jsonb_build_object(
          'code', 'ERR_INVALID_REQUEST',
          'message', 'offset must be a non-negative integer.'
        )
      );
    END IF;
    v_offset := (p_input->>'offset')::INTEGER;
  END IF;

  v_context := private.resolve_airport_page_context(v_airport_iata, v_locale);

  IF v_context->'error' IS NOT NULL
    AND v_context->'error' <> 'null'::JSONB
  THEN
    RETURN jsonb_build_object('data', NULL, 'meta', NULL, 'error', v_context->'error');
  END IF;

  v_airport_id := (v_context #>> '{data,airport_id}')::UUID;
  v_airport_page_id := (v_context #>> '{data,airport_page_id}')::UUID;
  v_data_version := (v_context #>> '{data,data_version}')::UUID;

  WITH normalized_routes AS (
    SELECT
      route.flight_route_id,
      CASE WHEN v_direction = 'outbound' THEN destination_airport.id ELSE origin_airport.id END
        AS counterpart_airport_id,
      CASE WHEN v_direction = 'outbound' THEN destination_airport.iata ELSE origin_airport.iata END
        AS counterpart_airport_iata,
      CASE WHEN v_direction = 'outbound' THEN destination_airport.name ELSE origin_airport.name END
        AS counterpart_airport_name,
      CASE WHEN v_direction = 'outbound' THEN destination_city.id ELSE origin_city.id END
        AS counterpart_city_id,
      CASE WHEN v_direction = 'outbound' THEN destination_city.name ELSE origin_city.name END
        AS counterpart_city_name,
      CASE WHEN v_direction = 'outbound' THEN destination_city.slug ELSE origin_city.slug END
        AS counterpart_city_slug,
      CASE WHEN v_direction = 'outbound' THEN destination_country.iso2 ELSE origin_country.iso2 END
        AS counterpart_country_code,
      CASE WHEN v_direction = 'outbound' THEN destination_country.name ELSE origin_country.name END
        AS counterpart_country_name,
      airline.iata AS airline_iata,
      airline.name AS airline_name,
      route.frequency_per_week,
      route.shortest_duration_minutes,
      route.longest_duration_minutes,
      route.seasonality
    FROM public.pseo_direct_routes route
    JOIN public.airports origin_airport
      ON origin_airport.id = route.origin_airport_id
    JOIN public.airports destination_airport
      ON destination_airport.id = route.destination_airport_id
    JOIN public.cities origin_city
      ON origin_city.id = route.origin_city_id
    JOIN public.cities destination_city
      ON destination_city.id = route.destination_city_id
    JOIN public.countries origin_country
      ON origin_country.id = route.origin_country_id
    JOIN public.countries destination_country
      ON destination_country.id = route.destination_country_id
    JOIN public.airlines airline
      ON airline.id = route.operating_airline_id
    WHERE route.data_version = v_data_version
      AND (
        (v_direction = 'outbound' AND route.origin_airport_id = v_airport_id)
        OR
        (v_direction = 'inbound' AND route.destination_airport_id = v_airport_id)
      )
  ),
  filtered_routes AS (
    SELECT *
    FROM normalized_routes route
    WHERE (cardinality(v_airlines) = 0 OR route.airline_iata = ANY(v_airlines))
      AND (cardinality(v_countries) = 0 OR route.counterpart_country_code = ANY(v_countries))
      AND (v_seasonality IS NULL OR route.seasonality = v_seasonality)
      AND (
        v_max_duration_minutes IS NULL
        OR route.shortest_duration_minutes <= v_max_duration_minutes
      )
  ),
  grouped_routes AS (
    SELECT
      counterpart_airport_id,
      counterpart_airport_iata,
      counterpart_airport_name,
      counterpart_city_id,
      counterpart_city_name,
      counterpart_city_slug,
      counterpart_country_code,
      counterpart_country_name,
      count(DISTINCT flight_route_id)::INTEGER AS route_count,
      count(DISTINCT airline_iata)::INTEGER AS airline_count,
      jsonb_agg(DISTINCT airline_iata ORDER BY airline_iata) AS airlines,
      CASE WHEN count(frequency_per_week) = 0 THEN NULL ELSE sum(frequency_per_week) END
        AS frequency_per_week,
      min(shortest_duration_minutes) AS shortest_duration_minutes,
      max(longest_duration_minutes) AS longest_duration_minutes
    FROM filtered_routes
    GROUP BY
      counterpart_airport_id,
      counterpart_airport_iata,
      counterpart_airport_name,
      counterpart_city_id,
      counterpart_city_name,
      counterpart_city_slug,
      counterpart_country_code,
      counterpart_country_name
  ),
  page AS (
    SELECT *
    FROM grouped_routes
    ORDER BY
      COALESCE(frequency_per_week, 0) DESC,
      route_count DESC,
      counterpart_city_name,
      counterpart_airport_iata
    LIMIT v_limit
    OFFSET v_offset
  )
  SELECT jsonb_build_object(
    'data', COALESCE((
      SELECT jsonb_agg(to_jsonb(page_item))
      FROM page page_item
    ), '[]'::JSONB),
    'meta', jsonb_build_object(
      'direction', v_direction,
      'total', (SELECT count(*) FROM grouped_routes),
      'limit', v_limit,
      'offset', v_offset,
      'facets', jsonb_build_object(
        'airlines', COALESCE((
          SELECT jsonb_agg(
            jsonb_build_object('code', facet.airline_iata, 'name', facet.airline_name, 'count', facet.count)
            ORDER BY facet.count DESC, facet.airline_iata
          )
          FROM (
            SELECT airline_iata, min(airline_name) AS airline_name, count(*)::INTEGER AS count
            FROM filtered_routes
            GROUP BY airline_iata
          ) facet
        ), '[]'::JSONB),
        'countries', COALESCE((
          SELECT jsonb_agg(
            jsonb_build_object(
              'code', facet.counterpart_country_code,
              'name', facet.counterpart_country_name,
              'count', facet.count
            )
            ORDER BY facet.count DESC, facet.counterpart_country_code
          )
          FROM (
            SELECT
              counterpart_country_code,
              min(counterpart_country_name) AS counterpart_country_name,
              count(*)::INTEGER AS count
            FROM filtered_routes
            GROUP BY counterpart_country_code
          ) facet
        ), '[]'::JSONB)
      ),
      'data_version', airport_page.data_version,
      'canonical_path', pseo_page.canonical_path,
      'is_indexable', airport_page.is_indexable
    ),
    'error', NULL
  )
  INTO v_result
  FROM public.airport_pages airport_page
  JOIN public.pseo_pages pseo_page
    ON pseo_page.id = airport_page.pseo_page_id
  WHERE airport_page.id = v_airport_page_id;

  RETURN v_result;
END;
$$;

REVOKE ALL ON FUNCTION public.rpc_search_airport_direct_routes(JSONB)
FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_search_airport_direct_routes(JSONB) TO service_role;
